Here is the root cause:
In `nr_output()`, when `sock_alloc_send_skb()` fails and returns `NULL`, the original `skb` passed to the function is not freed, causing a memory leak. This `skb` was allocated in `nr_sendmsg()` and never released on this error path.

Here is the patch:
  */
 void nr_output(struct sock *sk, struct sk_buff *skb)
 {
 	struct sk_buff *skbn;
 	unsigned char transport[NR_TRANSPORT_LEN];
 	int err, frontlen, len;

 	if (skb->len - NR_TRANSPORT_LEN > NR_MAX_PACKET_SIZE) {
 		/* Save a copy of the Transport Header */
 		skb_copy_from_linear_data(skb, transport, NR_TRANSPORT_LEN);
 		skb_pull(skb, NR_TRANSPORT_LEN);

 		frontlen = skb_headroom(skb);

 		while (skb->len > 0) {
-			if ((skbn = sock_alloc_send_skb(sk, frontlen + NR_MAX_PACKET_SIZE, 0, &err)) == NULL)
+			if ((skbn = sock_alloc_send_skb(sk, frontlen + NR_MAX_PACKET_SIZE, 0, &err)) == NULL) {
+				kfree_skb(skb);
 				return;
+			}

 			skb_reserve(skbn, frontlen);

 			len = (NR_MAX_PACKET_SIZE > skb->len) ? skb->len : NR_MAX_PACKET_SIZE;

 			/* Copy the user data */
 			skb_copy_from_linear_data(skb, skb_put(skbn, len), len);
 			skb_pull(skb, len);

 			/* Duplicate the Transport Header */
 			skb_push(skbn, NR_TRANSPORT_LEN);
 			skb_copy_to_linear_data(skbn, transport,
 						NR_TRANSPORT_LEN);
 			if (skb->len > 0)
 				skbn->data[4] |= NR_MORE_FLAG;

 			skb_queue_tail(&sk->sk_write_queue, skbn); /* Throw it on the queue */
 		}

 		kfree_skb(skb);
 	} else {
 		skb_queue_tail(&sk->sk_write_queue, skb);		/* Throw it on the queue */
 	}

 	nr_kick(sk);
 }



